def sembrar_permisos(apps, schema_editor):
    Permiso = apps.get_model("gym", "Permiso")
    Rol = apps.get_model("gym", "Rol")
    RolPermiso = apps.get_model("gym", "RolPermiso")

    permisos = {}
    for accion in ACCIONES:
        codigo = f"{RECURSO}:{accion}"
        permiso, _ = Permiso.objects.update_or_create(
            codigo=codigo,
            defaults={
                "recurso": RECURSO,
                "accion": accion,
                "descripcion": f"{DESCRIPCION_ACCION[accion]} {RECURSO}",
                "is_active": True,
            },
        )
        permisos[accion] = permiso.pk

    for nombre_rol, acciones in POLITICAS_POR_ROL.items():
        rol = Rol.objects.filter(nombre=nombre_rol).first()
        if rol is None:
            continue
        deseados = {permisos[accion] for accion in acciones}
        existentes = set(
            RolPermiso.objects.filter(rol_id=rol.pk).values_list(
                "permiso_id", flat=True
            )
        )
        RolPermiso.objects.bulk_create(
            [
                RolPermiso(rol_id=rol.pk, permiso_id=permiso_id)
                for permiso_id in deseados - existentes
            ]
        )


